with filtered_payments as (select *, substring(status, 1, 4) as status_prefix from payments where method <> 'cash' and hour(paid_at) between 10 and 17), agg as (select case when amount >= 1260 then 'high' when amount >= 380 then 'mid' else 'low' end as amount_bucket, method, concat_ws(', ', sort_array(collect_set(method))) as method_values from filtered_payments group by case when amount >= 1260 then 'high' when amount >= 380 then 'mid' else 'low' end, method) select amount_bucket, method from agg order by method, amount_bucket limit 3
